update public.dream_items d
set preview = s.preview, description = s.description, tags = s.tags,
    is_lucky = s.is_lucky, luck_index = s.luck_index
from (values
  ('animal-001', $q$재물이 들어오는 대표적인 길몽$q$, $q$품 안으로 돼지가 뛰어들거나 안기는 꿈은 한국 민속에서 재물이 들어오는 대표적인 길몽으로 꼽힌다. 예로부터 돼지는 넉넉함과 다산을 상징해 복권 구매나 사업 시작 등 재물과 관련된 결정을 앞둔 사람에게 좋은 징조로 해석되어 왔다. 다만 품에 안겼다가 다시 빠져나가면 들어온 재물이 곧 흩어질 수 있다는 뜻으로도 풀이된다.$q$, array['길몽','재물','돼지']::text[], 'lucky', 85),
  ('body-015', $q$위축되거나 자신감을 잃을 수 있다는 경고$q$, $q$자신의 몸이 점점 작아져 초라해지는 꿈은 현실에서 위축되거나 자신감을 잃을 수 있다는 경고로 전해진다. 몸집이 줄어드는 상징이 영향력이나 발언권이 약해지는 것과 연결되어 해석된다. 작아졌던 몸이 다시 원래대로 돌아왔다면 위축된 마음도 곧 회복된다는 뜻이다.$q$, array['흉몽','경고']::text[], 'unlucky', 33),
  ('body-031', $q$집안에 환자나 우환이 생기는 흉몽입니다.$q$, $q$머리카락을 양쪽으로 가르는 꿈은 근심이 생기거나 집안에 환자나 우환이 생깁니다.$q$, array[]::text[], 'unlucky', 25),
  ('body-032', $q$하는 일이 부진해지고 가족에게 불행한 일이 생기는 흉몽입니다.$q$, $q$억지로 머리카락을 자르는 꿈은 하는 일이 부진해지고 가족에게 불행한 일이 생깁니다.$q$, array[]::text[], 'unlucky', 11),
  ('body-033', $q$좋은 인연을 만나거나 귀인의 도움으로 교제가 성사되는 길몽입니다.$q$, $q$머리카락을 묶는 꿈은 좋은 인연을 만나거나 귀인의 도움으로 교제가 성사되는 길몽입니다.$q$, array[]::text[], 'lucky', 64),
  ('body-034', $q$스스로 자르면 걱정거리가 전부 해소되는 길몽입니다.$q$, $q$스스로 머리카락을 자르면 걱정거리가 모두 해소되고 소원을 성취하는 길몽입니다.$q$, array[]::text[], 'lucky', 93),
  ('body-035', $q$모함과 재산 손실, 가족 피해 등 큰 재난을 암시하는 흉몽입니다.$q$, $q$갑작스러운 탈모 꿈은 모함과 재산 손실, 가족 피해 등 큰 재난이 닥칠 흉몽입니다.$q$, array[]::text[], 'unlucky', 7),
  ('body-036', $q$귀인의 도움으로 사업이 발전하고 어려움을 극복하는 길몽입니다.$q$, $q$귀인의 도움으로 직장이나 사업이 발전하고 어려운 상황을 극복하게 되는 길몽입니다.$q$, array[]::text[], 'lucky', 68),
  ('body-037', $q$공적을 인정받아 상이나 훈장을 받고 명예를 얻는 길몽입니다.$q$, $q$머리카락이 윤기 나는 꿈은 공적을 인정받아 상이나 훈장을 받고 명예를 얻는 길몽입니다.$q$, array[]::text[], 'lucky', 85),
  ('body-038', $q$명예와 지위가 높아지고 수명이 길어지는 길몽입니다.$q$, $q$흰머리로 변하는 꿈은 명예와 지위가 높아지고 근심이 해소되며 수명이 길어지는 길몽입니다.$q$, array[]::text[], 'lucky', 88),
  ('body-039', $q$가정에 좋지 않은 일이 생기고 심리 상태가 불안정해지는 흉몽입니다.$q$, $q$가정에 좋지 않은 일이 생기거나 심리 상태가 방향을 잃고 불안정해지는 흉몽입니다.$q$, array[]::text[], 'unlucky', 39),
  ('crawled-001', $q$꿈에서 두렵고 무서운 감정을 느꼈다면 실제로 사고가 날 수 있는 흉몽으로 해석된다. 반대로$q$, $q$꿈에서 두렵고 무서운 감정을 느꼈다면 실제로 사고가 날 수 있는 흉몽으로 해석된다. 반대로 무섭지 않았다면 본인에게 아주 큰 변화가 생길 수 있음을 암시한다.$q$, array['조건부','흉몽','길몽']::text[], null, 50),
  ('crawled-002', $q$꿈 해몽상 땅은 재산과 생활터전, 집안의 여성(어머니·아내·할머니)을 뜻한다. 땅이 꺼지는$q$, $q$꿈 해몽상 땅은 재산과 생활터전, 집안의 여성(어머니·아내·할머니)을 뜻한다. 땅이 꺼지는 꿈은 재산상의 손실이 발생하거나 집안의 여성에게 안 좋은 일이 생긴다고 해석된다.$q$, array['흉몽']::text[], null, 20),
  ('crawled-003', $q$이빨은 본인의 가족을 상징한다. 꿈의 분위기에 따라 길몽과 흉몽으로 나뉜다. 가족 내 오랜$q$, $q$이빨은 본인의 가족을 상징한다. 꿈의 분위기에 따라 길몽과 흉몽으로 나뉜다. 가족 내 오랜 걱정거리가 해결되는 변화를 암시하기도 하고, 반대로 가족이나 주변 사람에게 불행이 닥칠 징조이기도 하다.$q$, array['조건부','길몽','흉몽']::text[], null, 50),
  ('crawled-004', $q$땅을 사는 것은 새로운 일을 시작한다는 의미로 받아들여진다. 지금까지 경험하지 못한 분야에$q$, $q$땅을 사는 것은 새로운 일을 시작한다는 의미로 받아들여진다. 지금까지 경험하지 못한 분야에 뛰어들게 되면 좋은 성과를 얻을 수 있는 길몽이다.$q$, array['길몽']::text[], null, 80),
  ('crawled-005', $q$지렁이가 땅속으로 숨어버리는 꿈을 꾸게 되면 사업장이나 집안에 사고나 우환이 생겨 근심 걱$q$, $q$지렁이가 땅속으로 숨어버리는 꿈을 꾸게 되면 사업장이나 집안에 사고나 우환이 생겨 근심 걱정이 있음을 뜻한다.$q$, array['흉몽']::text[], null, 20),
  ('crawled-006', $q$큰 규모의 총파업·분규·혁명이 발발하는 것을 상징한다. 개인적으로는 변동이 있거나 사소한 $q$, $q$큰 규모의 총파업·분규·혁명이 발발하는 것을 상징한다. 개인적으로는 변동이 있거나 사소한 일로 소송사건에 휘말릴 수 있다.$q$, array['흉몽']::text[], null, 20),
  ('crawled-007', $q$금붕어가 땅에 떨어져 어항에 집어넣는 꿈은 예술적 능력이 뛰어난 아이를 출산하게 된다는 태$q$, $q$금붕어가 땅에 떨어져 어항에 집어넣는 꿈은 예술적 능력이 뛰어난 아이를 출산하게 된다는 태몽이다.$q$, array['태몽']::text[], null, 70),
  ('crawled-008', $q$용이 땅에 있는 꿈은 아이의 인물이 뛰어나나 세력을 얻지는 못한다는 태몽이다. 승천하지 못$q$, $q$용이 땅에 있는 꿈은 아이의 인물이 뛰어나나 세력을 얻지는 못한다는 태몽이다. 승천하지 못한 용처럼 평범하게 살 아이를 상징한다.$q$, array['태몽']::text[], null, 70),
  ('crawled-009', $q$연못을 만들기 위해 땅을 파는 꿈은 후회할 일이 생긴다는 것을 암시한다.$q$, $q$연못을 만들기 위해 땅을 파는 꿈은 후회할 일이 생긴다는 것을 암시한다.$q$, array['흉몽']::text[], null, 20),
  ('crawled-010', $q$어떤 일을 깨끗이 처리하거나 비밀에 부쳐야 할 처지에 놓인다는 것을 상징한다.$q$, $q$어떤 일을 깨끗이 처리하거나 비밀에 부쳐야 할 처지에 놓인다는 것을 상징한다.$q$, array['보통']::text[], null, 50),
  ('crawled-011', $q$부정한 일을 하거나 정부와 적대되는 일을 하게 된다는 것을 상징한다.$q$, $q$부정한 일을 하거나 정부와 적대되는 일을 하게 된다는 것을 상징한다.$q$, array['흉몽']::text[], null, 20),
  ('crawled-012', $q$추진 중인 일이 많은 사람들을 감동시키게 된다는 것을 암시한다.$q$, $q$추진 중인 일이 많은 사람들을 감동시키게 된다는 것을 암시한다.$q$, array['길몽']::text[], null, 80),
  ('crawled-013', $q$연구 자료를 수집할 일이 생기거나 창작품을 발표하게 된다는 것을 암시한다.$q$, $q$연구 자료를 수집할 일이 생기거나 창작품을 발표하게 된다는 것을 암시한다.$q$, array['길몽']::text[], null, 80),
  ('crawled-014', $q$상대방과 작은 일로 싸움을 하게 된다. 돈을 조금 가지고 있으면 걱정거리가 생긴다.$q$, $q$상대방과 작은 일로 싸움을 하게 된다. 돈을 조금 가지고 있으면 걱정거리가 생긴다.$q$, array['흉몽']::text[], null, 20),
  ('crawled-015', $q$자기가 원하던 일이 뜻대로 이루어지지 않는다는 것을 암시한다.$q$, $q$자기가 원하던 일이 뜻대로 이루어지지 않는다는 것을 암시한다.$q$, array['흉몽']::text[], null, 20),
  ('crawled-016', $q$재산이 불어나고 저축이 많아진다는 것을 상징하는 길몽이다.$q$, $q$재산이 불어나고 저축이 많아진다는 것을 상징하는 길몽이다.$q$, array['길몽']::text[], null, 80),
  ('crawled-017', $q$자신이나 주변에서 불길한 일이 일어날 징조이다.$q$, $q$자신이나 주변에서 불길한 일이 일어날 징조이다.$q$, array['흉몽']::text[], null, 20),
  ('crawled-018', $q$집을 새로 장만하거나 새 직장을 구한다. 땅을 파서 자신을 묻었다면 재산이 크게 늘어날 징$q$, $q$집을 새로 장만하거나 새 직장을 구한다. 땅을 파서 자신을 묻었다면 재산이 크게 늘어날 징조다.$q$, array['길몽']::text[], null, 80),
  ('crawled-019', $q$땅에 파묻히는 것은 재물과 돈이 파묻힌다는 암시다. 파묻혀서 질식하는 꿈은 곤란과 불안을 $q$, $q$땅에 파묻히는 것은 재물과 돈이 파묻힌다는 암시다. 파묻혀서 질식하는 꿈은 곤란과 불안을 나타낸다.$q$, array['흉몽']::text[], null, 20),
  ('crawled-020', $q$생활환경이 안정될 조짐으로 좋은 꿈이다. 또는 술대접을 받을 일이 생긴다.$q$, $q$생활환경이 안정될 조짐으로 좋은 꿈이다. 또는 술대접을 받을 일이 생긴다.$q$, array['길몽']::text[], null, 80),
  ('crawled-021', $q$부동산, 권력, 명성 등을 얻고 재복이 따른다는 길몽이다.$q$, $q$부동산, 권력, 명성 등을 얻고 재복이 따른다는 길몽이다.$q$, array['길몽']::text[], null, 80),
  ('crawled-022', $q$여러 사람들로부터 무시당하거나 남의 것을 모방하다 망신을 당한다.$q$, $q$여러 사람들로부터 무시당하거나 남의 것을 모방하다 망신을 당한다.$q$, array['흉몽']::text[], null, 20),
  ('crawled-023', $q$실업자는 일자리를 얻고 직장인은 중요한 부서로 이동할 암시다. 단, 노약자라면 건강이 악화$q$, $q$실업자는 일자리를 얻고 직장인은 중요한 부서로 이동할 암시다. 단, 노약자라면 건강이 악화될 암시이기도 하다.$q$, array['조건부','길몽','흉몽']::text[], null, 50),
  ('crawled-024', $q$사업을 추진하며 주도적인 위치에서 일하거나 세력을 넓힌다는 것을 상징한다.$q$, $q$사업을 추진하며 주도적인 위치에서 일하거나 세력을 넓힌다는 것을 상징한다.$q$, array['길몽']::text[], null, 80),
  ('crawled-025', $q$직위 하향, 신분 몰락을 가져오거나 시험·연애 등에 실패를 거듭한다.$q$, $q$직위 하향, 신분 몰락을 가져오거나 시험·연애 등에 실패를 거듭한다.$q$, array['흉몽']::text[], null, 20),
  ('crawled-026', $q$뜻한 바대로 소원이 성취되고 모든 일에 장애 없이 잘 풀린다.$q$, $q$뜻한 바대로 소원이 성취되고 모든 일에 장애 없이 잘 풀린다.$q$, array['길몽']::text[], null, 80),
  ('crawled-027', $q$우울한 일이 생기거나 근심거리가 있음을 예시한다.$q$, $q$우울한 일이 생기거나 근심거리가 있음을 예시한다.$q$, array['흉몽']::text[], null, 20),
  ('crawled-028', $q$주위의 간교함 때문에 사업이 점점 부실해지거나 신분 또는 자존심이 실추된다.$q$, $q$주위의 간교함 때문에 사업이 점점 부실해지거나 신분 또는 자존심이 실추된다.$q$, array['흉몽']::text[], null, 20),
  ('crawled-029', $q$전에 없던 일이 활기를 띠고 성과를 거둔다. 땅이 갈라진 깊은 곳까지 내려다보았다면 학문 $q$, $q$전에 없던 일이 활기를 띠고 성과를 거둔다. 땅이 갈라진 깊은 곳까지 내려다보았다면 학문 등에 깊이 몰두하게 된다.$q$, array['길몽']::text[], null, 80),
  ('crawled-030', $q$시험에 합격하거나 소망하던 취직이 이루어진다는 길몽이다.$q$, $q$시험에 합격하거나 소망하던 취직이 이루어진다는 길몽이다.$q$, array['길몽']::text[], null, 80),
  ('crawled-031', $q$생각지도 못한 불안, 공포, 질병 등이 발생하여 한동안 지속된다.$q$, $q$생각지도 못한 불안, 공포, 질병 등이 발생하여 한동안 지속된다.$q$, array['흉몽']::text[], null, 20),
